package nipCO

import (
	"encoding/json"
	"errors"
	"fmt"

	"github.com/ohstr/nmilat/nipcash"
	"github.com/ohstr/nmilat/nipcash/transport"
)

// CashOrderParams is a cash_order request as a client builds it (NIP-CO
// §Request). Recipient is exactly one recipient: nipcash.Pubkey,
// nipcash.ConnectionKey or a *nipcash.CashTarget (use NewCashOrderTarget, whose
// buyer key is usable). Notify and RequestID are generated by the client when
// empty.
type CashOrderParams struct {
	Recipient    nipcash.Recipient
	AmountMillis uint64
	Payment      string
	Notify       string
	RequestID    string
}

// CashOrderRequest is cash_order's wire request: exactly the five keys
// recipient, amount_millis, payment, notify and request_id. The recipient carries
// identity_type, identity_value and, for connection_key, ia_pubkey; never an
// amount.
type CashOrderRequest struct {
	Recipient    nipcash.RecipientParam `json:"recipient"`
	AmountMillis uint64                 `json:"amount_millis"`
	Payment      string                 `json:"payment"`
	Notify       string                 `json:"notify"`
	RequestID    string                 `json:"request_id"`

	// defect is the step-3 refusal ParseCashOrderRequest recorded, reported by
	// CheckPlacement in step order.
	defect *OrderError
}

type orderRecipientWire struct {
	IdentityType  string `json:"identity_type"`
	IdentityValue string `json:"identity_value"`
	IAPubkey      string `json:"ia_pubkey,omitempty"`
}

type cashOrderWire struct {
	Recipient    orderRecipientWire `json:"recipient"`
	AmountMillis uint64             `json:"amount_millis"`
	Payment      string             `json:"payment"`
	Notify       string             `json:"notify"`
	RequestID    string             `json:"request_id"`
}

// MarshalJSON writes the five keys, the recipient without an amount.
func (r CashOrderRequest) MarshalJSON() ([]byte, error) {
	return json.Marshal(cashOrderWire{
		Recipient: orderRecipientWire{IdentityType: r.Recipient.IdentityType,
			IdentityValue: r.Recipient.IdentityValue, IAPubkey: r.Recipient.IAPubkey},
		AmountMillis: r.AmountMillis, Payment: r.Payment, Notify: r.Notify, RequestID: r.RequestID,
	})
}

// ValidNotify reports a notify value of the wire form: 64 lowercase hex.
func ValidNotify(s string) bool { return isLowerHex(s, 64) }

func isLowerHex(s string, n int) bool {
	if len(s) != n {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// Request builds the wire request. It refuses a nil recipient, an amount of 0,
// an on-chain amount that is not a multiple of 1000, a payment other than
// lightning and onchain, a notify that is not 64 lowercase hex and an invalid
// request_id; the recipient is validated as a mint_cash recipient (a
// connection_key needs its ia_pubkey). A cash recipient sends its commitment.
func (p CashOrderParams) Request() (CashOrderRequest, error) {
	if p.Recipient == nil {
		return CashOrderRequest{}, fmt.Errorf("%w: %w", ErrOrderRequest, nipcash.ErrNoRecipients)
	}
	if p.AmountMillis == 0 {
		return CashOrderRequest{}, fmt.Errorf("%w: %w", ErrOrderRequest, nipcash.ErrZeroAmount)
	}
	switch p.Payment {
	case PaymentLightning:
	case PaymentOnchain:
		if p.AmountMillis%1000 != 0 {
			return CashOrderRequest{}, fmt.Errorf("%w: an on-chain amount is a multiple of 1000 millis", ErrOrderRequest)
		}
	default:
		return CashOrderRequest{}, fmt.Errorf("%w: payment %q", ErrOrderRequest, p.Payment)
	}
	if !ValidNotify(p.Notify) {
		return CashOrderRequest{}, fmt.Errorf("%w: notify is 64 lowercase hex", ErrOrderRequest)
	}
	mint, err := nipcash.MintCashParams{
		Recipients: []nipcash.Allocation{nipcash.Send(p.Recipient, p.AmountMillis)},
		RequestID:  p.RequestID,
	}.Request()
	if err != nil {
		return CashOrderRequest{}, fmt.Errorf("%w: %w", ErrOrderRequest, err)
	}
	rp := mint.Recipients[0]
	rp.AmountMillis = 0
	return CashOrderRequest{Recipient: rp, AmountMillis: p.AmountMillis, Payment: p.Payment,
		Notify: p.Notify, RequestID: p.RequestID}, nil
}

// ErrNoBuyerKey is an order item built without a buyer key: a proofless order is
// a local programming error, never sent.
var ErrNoBuyerKey = errors.New("nipCO: a cash_order item needs the buyer key to sign its proof")

// Item builds the cash_order item for the private transport (NIP-CO §The
// Item): target the Order connection pubkey (TLV 0), the item proof signed by
// the buyer key, the bill proof by the connection secret (TLV 2).
func (p CashOrderParams) Item(id, target, connSecret, buyerKeyHex string, b nipcash.ItemBinding) (transport.Item, error) {
	if buyerKeyHex == "" {
		return transport.Item{}, ErrNoBuyerKey
	}
	req, err := p.Request()
	if err != nil {
		return transport.Item{}, err
	}
	return nipcash.BuildItem(id, target, connSecret, nipcash.MethodCashOrder, req, nipcash.BySigning(buyerKeyHex), b)
}

// forbiddenOrderKeys are what a Hub refuses in a cash_order request with
// BAD_REQUEST (NIP-CO §Request).
var forbiddenOrderKeys = []string{"recipients", "expiry", "cash_secret", "idempotency_key", "min_transfer_millis"}

// ParseCashOrderRequest is the Hub's reading of a cash_order request. It returns
// the decoded request together with any step-3 defect as an *OrderError
// (BAD_REQUEST, Step 3): a forbidden key, a recipient that is not one valid
// pubkey, connection_key (with ia_pubkey) or cash shape, an amount that is not a
// positive integer, an on-chain amount not a multiple of 1000, a payment other
// than the two, a notify that is not 64 lowercase hex, an invalid request_id.
// The defect is also recorded on the request, so CheckPlacement reports it in
// NIP-CO step order. Only a request that is not an object, or whose string fields
// are not strings, returns no request.
func ParseCashOrderRequest(raw json.RawMessage) (*CashOrderRequest, error) {
	obj, err := object(raw)
	if err != nil {
		return nil, badRequest("the request is not a JSON object")
	}
	req := &CashOrderRequest{}
	for _, f := range []struct {
		name string
		dst  *string
	}{{"payment", &req.Payment}, {"notify", &req.Notify}, {"request_id", &req.RequestID}} {
		if v, ok := obj[f.name]; ok {
			if err := json.Unmarshal(v, f.dst); err != nil {
				return nil, badRequest(f.name + " is not a string")
			}
		}
	}
	defect := func() *OrderError {
		for _, k := range forbiddenOrderKeys {
			if _, ok := obj[k]; ok {
				return badRequest("a cash_order carries no " + k)
			}
		}
		rv, ok := obj["recipient"]
		if !ok {
			return badRequest("recipient is required")
		}
		rp, msg := parseOrderRecipient(rv)
		req.Recipient = rp
		if msg != "" {
			return badRequest(msg)
		}
		av, ok := obj["amount_millis"]
		if !ok {
			return badRequest("amount_millis is required")
		}
		amount, err := uintValue(av)
		if err != nil || amount == 0 {
			return badRequest("amount_millis is a positive integer")
		}
		req.AmountMillis = amount
		switch req.Payment {
		case PaymentLightning:
		case PaymentOnchain:
			if amount%1000 != 0 {
				return badRequest("an on-chain amount_millis is a multiple of 1000")
			}
		default:
			return badRequest(fmt.Sprintf("payment %q is not lightning or onchain", req.Payment))
		}
		if !ValidNotify(req.Notify) {
			return badRequest("notify is 64 lowercase hex")
		}
		if !nipcash.ValidRequestID(req.RequestID) {
			return badRequest("request_id is malformed")
		}
		return nil
	}()
	if defect != nil {
		req.defect = defect
		return req, defect
	}
	return req, nil
}

// parseOrderRecipient reads one recipient; msg is the refusal, "" when valid.
func parseOrderRecipient(raw json.RawMessage) (nipcash.RecipientParam, string) {
	var w orderRecipientWire
	if _, err := object(raw); err != nil {
		return nipcash.RecipientParam{}, "recipient is one object"
	}
	if err := json.Unmarshal(raw, &w); err != nil {
		return nipcash.RecipientParam{}, "recipient fields are strings"
	}
	rp := nipcash.RecipientParam{IdentityType: w.IdentityType, IdentityValue: w.IdentityValue, IAPubkey: w.IAPubkey}
	if !isLowerHex(w.IdentityValue, 64) {
		return rp, "recipient identity_value is 64 lowercase hex"
	}
	switch w.IdentityType {
	case "pubkey", "cash":
		if w.IAPubkey != "" {
			return rp, "only a connection_key recipient carries ia_pubkey"
		}
	case "connection_key":
		if !isLowerHex(w.IAPubkey, 64) {
			return rp, "a connection_key recipient needs its ia_pubkey"
		}
	default:
		return rp, fmt.Sprintf("recipient identity_type %q is not pubkey, connection_key or cash", w.IdentityType)
	}
	return rp, ""
}
